def _tool(slug, name, emoji, h1, desc, intro, skills, fields, prompt, template, checks, selfcheck, tips, faq, ext='txt', related=()):
    return dict(slug=slug, name=name, cat='writing', emoji=emoji, h1=h1, desc=desc, intro=intro, skills=skills, fields=fields, prompt=prompt, template=template, checks=checks, selfcheck=selfcheck, tips=tips, faq=faq, course='prompt', related=list(related), ext=ext)

